import { registerRecipeEases } from '../effects/recipe-eases'
import { MOTION_RUNTIME_ASSET } from './motion-runtime-asset.generated'

/**
 * The part of `motion-runtime@v1` the stage uses (F40: `init / seek / dispose` plus the read endpoints `describe /
 * inspect / hitTest`), declared structurally because the UI image cannot import from `packages/`. The runtime itself
 * is the vendored browser copy (`public/motion-runtime/`, generated by `packages/motion-runtime/scripts/generate-ui-copy.mjs`)
 * loaded as a classic script; nothing here re-implements layout or timing.
 */

export type RuntimeHandle = string

export interface RuntimeDescribeNode {
  handle: RuntimeHandle
  kind: string
  role: string
  hidden: boolean
  children: RuntimeDescribeNode[]
}

export interface RuntimeNodeInspection {
  element: 'node'
  handle: RuntimeHandle
  kind: string
  role: string
  props: Record<string, number | string>
  box: {
    canvas: { x: number; y: number; width: number; height: number }
    normalized: { x: number; y: number; width: number; height: number }
  }
  effective_opacity: number
  visible: boolean
}

export type RuntimeHitRegion = { point: { x: number; y: number } } | { box: { x: number; y: number; w: number; h: number } }

export interface RuntimeHit {
  handle: RuntimeHandle
  kind: string
  role: string
  ancestors: RuntimeHandle[]
}

export interface MotionRuntimeLike {
  readonly version: string
  init(
    ir: unknown,
    params?: Record<string, unknown>,
    assets?: Record<string, string>,
    options?: { mode?: 'preview' | 'final'; container?: HTMLElement; font_set_hash?: string },
  ): { duration_frames: number; warnings: { code: string; message: string }[] }
  seek(frame: number): void
  dispose(): void
  describe(): { nodes: RuntimeDescribeNode[]; duration_frames: number }
  inspect(handles: readonly RuntimeHandle[], frame: number): RuntimeNodeInspection[]
  hitTest(frame: number, region: RuntimeHitRegion): RuntimeHit[]
}

export interface MotionRuntimeModule {
  createMotionRuntime(): MotionRuntimeLike
  MOTION_RUNTIME_VERSION: string
  MOTION_RUNTIME_API: string
  /**
   * Spark effects library: the runtime's ease curves (IR ease name -> function), so the editor samples the shared recipes on
   * the curves the runtime draws with (`lib/spark/effects/recipe-eases.ts`). Absent in a bundle older than the library.
   */
  easeFunction?(ease: string): (t: number) => number
}

/** Hands the loaded runtime's ease curves to the recipe sampler (`recipe-eases.ts`). */
function registerEases(module: MotionRuntimeModule): MotionRuntimeModule {
  if (typeof module.easeFunction === 'function') registerRecipeEases(module.easeFunction)
  return module
}

export class MotionRuntimeLoadError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'MotionRuntimeLoadError'
  }
}

let loading: Promise<MotionRuntimeModule> | null = null

type ScriptHost = {
  createElement(tag: 'script'): { src: string; integrity: string; crossOrigin: string; async: boolean; onload: (() => void) | null; onerror: (() => void) | null }
  head: { appendChild(node: unknown): unknown }
}

/**
 * Loads the vendored runtime once per page (a classic script exposing `globalThis.YoutorchMotionRuntime`). The script
 * carries its SRI digest, so a tampered or stale file is refused by the browser instead of drawing a different picture.
 */
export function loadMotionRuntime(
  options: { asset?: typeof MOTION_RUNTIME_ASSET; host?: ScriptHost; read?: () => MotionRuntimeModule | undefined } = {},
): Promise<MotionRuntimeModule> {
  const asset = options.asset ?? MOTION_RUNTIME_ASSET
  const read = options.read ?? (() => (globalThis as { YoutorchMotionRuntime?: MotionRuntimeModule }).YoutorchMotionRuntime)
  const existing = read()
  if (existing) return Promise.resolve(registerEases(existing))
  if (loading) return loading
  const host = options.host ?? (globalThis.document as unknown as ScriptHost | undefined)
  if (!host) return Promise.reject(new MotionRuntimeLoadError('The motion runtime needs a browser.'))
  loading = new Promise<MotionRuntimeModule>((resolve, reject) => {
    const script = host.createElement('script')
    script.src = asset.path
    script.integrity = asset.integrity
    script.crossOrigin = 'anonymous'
    script.async = true
    script.onload = () => {
      const loaded = read()
      if (loaded) resolve(registerEases(loaded))
      else reject(new MotionRuntimeLoadError('The motion runtime script did not expose its API.'))
    }
    script.onerror = () => reject(new MotionRuntimeLoadError('The motion runtime script could not be loaded.'))
    host.head.appendChild(script)
  })
  // A failed load may be retried (the next mount asks again).
  loading.catch(() => {
    loading = null
  })
  return loading
}

export function resetMotionRuntimeLoaderForTests(): void {
  loading = null
}
